package com.example.campsitelottery

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test
import java.util.Date

/**
 * Documentation generated by Claude
 * Tests the review flow against [InMemoryReviewRepository].
 */
class InMemoryReviewRepositoryTest {

    private var now = 1_000L
    private lateinit var repo: InMemoryReviewRepository

    @Before
    fun setUp() {
        repo = InMemoryReviewRepository(
            campsites = listOf(Campsite(campsiteId = "site1", ownerId = "owner")),
            clock = { Date(now++) },
        )
    }

    private fun submit(userId: String, text: String, campsiteId: String = "site1", name: String = "Name"): Exception? {
        var error: Exception? = null
        repo.submitReview(campsiteId, userId, name, text, onSuccess = {}, onFailure = { error = it })
        return error
    }

    private fun reviews(campsiteId: String = "site1"): List<Review> {
        var result: List<Review>? = null
        repo.getReviews(campsiteId, onSuccess = { result = it }, onFailure = { throw it })
        return result!!
    }

    @Test
    fun noReviewsBeforePosting() {
        assertTrue(reviews().isEmpty())
    }

    @Test
    fun postedReviewIsSavedTrimmed() {
        assertNull(submit("guest", "  Lovely views  ", name = " Sam "))
        val saved = reviews().single()
        assertEquals("guest", saved.userId)
        assertEquals("Sam", saved.authorName)
        assertEquals("Lovely views", saved.text)
        assertNotNull(saved.updatedAt)
    }

    @Test
    fun postingAgainReplacesTheEarlierReview() {
        submit("guest", "First")
        submit("guest", "Second")
        assertEquals(listOf("Second"), reviews().map { it.text })
    }

    @Test
    fun reviewsAreNewestFirst() {
        submit("a", "from a")
        submit("b", "from b")
        submit("a", "a edited")
        assertEquals(listOf("a", "b"), reviews().map { it.userId })
    }

    @Test
    fun ownerCannotReviewOwnCampsite() {
        assertNotNull(submit("owner", "Best campsite ever"))
        assertTrue(reviews().isEmpty())
    }

    @Test
    fun invalidTextIsRejected() {
        assertNotNull(submit("guest", "   "))
        assertNotNull(submit("guest", "x".repeat(ReviewPolicy.MAX_LENGTH + 1)))
        assertTrue(reviews().isEmpty())
    }

    @Test
    fun unknownCampsiteIsRejected() {
        assertNotNull(submit("guest", "Hello", campsiteId = "missing"))
    }

    @Test
    fun reviewsAreKeptPerCampsite() {
        val repo = InMemoryReviewRepository(
            reviews = mapOf("other" to listOf(Review(userId = "x", text = "elsewhere"))),
        )
        var site1: List<Review>? = null
        repo.getReviews("site1", onSuccess = { site1 = it }, onFailure = { throw it })
        assertTrue(site1!!.isEmpty())
    }

    @Test
    fun failuresAreReported() {
        repo.failWith = IllegalStateException("offline")
        var error: Exception? = null
        repo.getReviews("site1", onSuccess = {}, onFailure = { error = it })
        assertEquals("offline", error?.message)
        assertEquals("offline", submit("guest", "Hi")?.message)
    }
}
